class Domain:
    """This class serves as a generic dummy to avoid cross referencing in the
    KeyMap module and allow implementation of more abstract KeyMaps.
    Also later extensions can start there as they might not derive from KeyMap
    """

    _IDENTIFIER = "Domain"
    _IDENTIFIER_SHORT = "SC"
    _enum = 0

    @autoname
    def __init__(self, *, name):
        self._name = name

        # start empty
        self._size = 0
        # contain nested keymaps, regions or entries
        self._content = []

        # remember what you are attached to
        self._parents = []

        # start with False, better safe than sorry
        self._is_ud_flag = False

    @property
    def name(self):
        """get name (protected access)"""
        return self._name

    @name.setter
    def name(self, name):
        warnings.warn(
            "Bad programmer, bad! But seriously, be careful with renaming."
        )
        self._name = name

    @property
    def size(self):
        """get size (protected access)"""
        return self._size

    def __str__(self):
        self.update()
        return f"<{self._IDENTIFIER} '{self.name}'>"

    def __repr__(self):
        self.update()
        return f"<{self._IDENTIFIER_SHORT}[{self.name}]>"

    def __len__(self):
        self.update()
        return self._size

    def update(self):
        """user-friendly update procedure. Skips update if already up to date,
        asserts up-to-date flag and"""
        ret = True
        if not self.is_ud:
            ret = self._update()
        assert ret, "update did not succeed"
        return self

    def _update(self):
        """placeholder for update"""
        return True

    @property
    def is_ud(self) -> bool:
        """read-only access to update flag"""
        return self._is_ud_flag

    def flag_ud(self):
        """mark for update"""
        self._is_ud_flag = False
        for parent in self._parents:
            parent.flag_ud()

    @staticmethod
    def from_file(filename) -> KeyMap:
        """get the keymap from a file"""
        with open(filename, "rb") as handle:
            ret = pickle.load(handle)
        ret.flag_ud()
        ret.__class__._enum += 1
        ret.update()
        return ret

    def to_file(self, filename) -> None:
        """write the keymap to a file"""
        self.update()
        with open(filename, "wb") as handle:
            pickle.dump(self, handle)

    def add_parent(self, parent):
        """add as a parent if not yet there"""
        if parent not in self._parents:
            self._parents.append(parent)


